@transaction.atomic
def carregar_modelos(apps, schema_editor):
    Modelo = apps.get_model("workspace", "ProjetoCronogramaModelo")
    Etapa = apps.get_model("workspace", "ProjetoCronogramaEtapaModelo")
    Tarefa = apps.get_model("workspace", "ProjetoCronogramaTarefaModelo")
    Subtarefa = apps.get_model("workspace", "ProjetoCronogramaSubtarefaModelo")
    Projeto = apps.get_model("workspace", "Projeto")

    for codigo, dados in CRONOGRAMAS.items():
        modelo, _ = Modelo.objects.update_or_create(
            codigo=codigo,
            defaults={
                "nome": dados["nome"],
                "descricao": "Cronograma padrão por tipo de projeto e metodologia.",
                "metodologia": dados["metodologia"],
                "ativo": True,
                "sistema": True,
            },
        )
        # Mantém projetos já vinculados ao modelo coerentes com a sua
        # metodologia, sem recriar nem alterar o cronograma efetivado.
        Projeto.objects.filter(cronograma_modelo=modelo).update(
            metodologia=dados["metodologia"]
        )
        ordens_etapas = set(dados["etapas"])
        modelo.etapas.exclude(ordem__in=ordens_etapas).delete()

        for ordem_etapa, dados_etapa in dados["etapas"].items():
            etapa, _ = Etapa.objects.update_or_create(
                modelo=modelo,
                ordem=ordem_etapa,
                defaults={
                    "nome": dados_etapa["nome"],
                    "descricao": dados_etapa["descricao"],
                    "tipo": "sprint",
                    "offset_inicio_dias_uteis": (ordem_etapa - 1) * 3,
                    "duracao_dias_uteis": 3,
                },
            )
            ordens_tarefas = set(dados_etapa["tarefas"])
            etapa.tarefas.exclude(ordem__in=ordens_tarefas).delete()

            for ordem_tarefa, dados_tarefa in dados_etapa["tarefas"].items():
                tarefa, _ = Tarefa.objects.update_or_create(
                    etapa=etapa,
                    ordem=ordem_tarefa,
                    defaults={
                        "nome": dados_tarefa["nome"],
                        "descricao": "",
                        "tipo": "tarefa",
                        "categoria": "outro",
                        "offset_inicio_dias_uteis": min(ordem_tarefa - 1, 2),
                        "duracao_dias_uteis": 1,
                        "peso": "1.00",
                        "obrigatoria": True,
                    },
                )
                ordens_subtarefas = {item[0] for item in dados_tarefa["subtarefas"]}
                tarefa.subtarefas.exclude(ordem__in=ordens_subtarefas).delete()
                for ordem_subtarefa, descricao in dados_tarefa["subtarefas"]:
                    Subtarefa.objects.update_or_create(
                        tarefa=tarefa,
                        ordem=ordem_subtarefa,
                        defaults={"descricao": descricao, "obrigatoria": True},
                    )


